<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\PeriodGuard;
class AcademicControlController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head')||$r->user()->canDo('students.manage'),403);}
 public function index(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get();$gid=$r->integer('group')?:$groups->first()?->id;$students=collect();if($gid){$mq=DB::table('student_group_memberships as m')->join('students as s','s.id','=','m.student_id')->where('m.academic_period_id',$p->id)->where('m.study_group_id',$gid)->where('m.status','active');$students=$mq->exists()?$mq->select('s.*')->orderBy('s.last_name')->get():DB::table('students')->where('current_group_id',$gid)->where('status','active')->orderBy('last_name')->get();foreach($students as $s){$res=DB::table('semester_results')->where(['academic_period_id'=>$p->id,'student_id'=>$s->id])->get();$legacy=$res->filter(fn($x)=>in_array(mb_strtolower((string)$x->value),['2','незачет','незачёт','не зачтено']))->count();$latest=DB::table('attestation_attempts as aa')->join('attestation_sheets as sh','sh.id','=','aa.attestation_sheet_id')->where(['sh.academic_period_id'=>$p->id,'aa.student_id'=>$s->id])->whereRaw('aa.attempt_no=(select max(a2.attempt_no) from attestation_attempts a2 where a2.attestation_sheet_id=aa.attestation_sheet_id and a2.student_id=aa.student_id)')->where('aa.passed',0)->count();$s->debts=max($legacy,$latest);$s->results=$res->count();$s->unexcused_absences=DB::table('attendance_records as a')->join('lesson_occurrences as l','l.id','=','a.lesson_occurrence_id')->where(['a.student_id'=>$s->id,'l.academic_period_id'=>$p->id,'a.status'=>'absent'])->count();$s->avg_grade=DB::table('grade_records as gr')->join('lesson_occurrences as l','l.id','=','gr.lesson_occurrence_id')->where(['gr.student_id'=>$s->id,'l.academic_period_id'=>$p->id])->avg(DB::raw('CAST(gr.value AS DECIMAL(4,2))'));$s->risk_reasons=collect();if($s->debts>0)$s->risk_reasons->push('академическая задолженность');if($s->unexcused_absences>=5)$s->risk_reasons->push('5+ неуважительных пропусков');if($s->avg_grade!==null&&$s->avg_grade<3.0)$s->risk_reasons->push('средний балл ниже 3,0');$s->admission=DB::table('attestation_admissions')->where(['academic_period_id'=>$p->id,'student_id'=>$s->id])->whereNull('subject_id')->first();}}return view('academic-office.control',compact('p','groups','gid','students'));}
 public function admission(Request $r,$student){$this->ok($r);$p=$r->attributes->get('academic_period');PeriodGuard::writable($p->id);$d=$r->validate(['status'=>'required|in:admitted,conditional,not_admitted','reason'=>'nullable|string|max:5000']);DB::table('attestation_admissions')->updateOrInsert(['academic_period_id'=>$p->id,'student_id'=>$student,'subject_id'=>null],array_merge($d,['decided_by'=>$r->user()->id,'decided_at'=>now(),'created_at'=>now(),'updated_at'=>now()]));return back()->with('success','Решение о допуске сохранено.');}
}